from pathlib import Path
import pandas as pd,json,gzip,lzma
P=Path(__file__).resolve().parent;S=P.parent;K=['season','fixture','code','field']
def save(d,n):
 b=d.to_csv(index=False).encode();(P/'results'/n).write_bytes(lzma.compress(b) if n.endswith('.xz') else gzip.compress(b,mtime=0) if n.endswith('.gz') else b)
def main():
 before=pd.read_csv(S/'bulk_batch2/results/requirements.csv.xz',low_memory=False);assert len(before)==775248 and before.is_open.sum()==24285
 val=json.loads((P/'joint_validation_summary.json').read_text());assert val['qualified']
 layer=pd.read_csv(S/'assist_touch_bounds/results/overlay.csv.gz');layer['method']='qualified_positive_event_actor_bounds';assert layer.field.eq('assists_2026_27').all() and not layer.duplicated(K).any() and layer.value.notna().all() and layer.value.mod(1).eq(0).all() and layer.value.ge(0).all()
 rows=before.reset_index(names='_row').merge(layer[K+['value','method']],on=K,validate='one_to_one',suffixes=('_old',''));assert len(rows)==len(layer) and rows.is_open.all() and rows.value_old.isna().all();assert rows.loc[~rows.field.eq('assists_2026_27'),'status'].eq('missing_data').all()
 out=before.copy(deep=True);ix=rows._row.to_numpy();out.loc[ix,'value']=rows.value.to_numpy();out.loc[ix,'is_zero']=rows.value.eq(0).to_numpy()
 for is_assist in [False,True]:
  ind=rows.loc[rows.field.eq('assists_2026_27').eq(is_assist),'_row'].to_numpy();quality='assist_positive_event_bounds_joint_temporal_shared_opta_review' if is_assist else 'primary_player_identity_and_exact_conservation_shared_opta_review';prov='assist_touch_bounds/results/candidate_exclusions.csv.gz; bulk_batch3/joint_validation_summary.json' if is_assist else 'primary_gap_recovery/predictions.csv.gz + conservation.csv + sources.json'
  for c,v in dict(is_open=False,status='documented_source_reconciliation',needs_external_quality_review=True,quality_status=quality,provenance=prov).items():out.loc[ind,c]=v
 mutable={'value','is_zero','is_open','status','needs_external_quality_review','quality_status','provenance'};protected=[c for c in before if c not in mutable];pd.testing.assert_frame_equal(before[protected],out[protected]);pd.testing.assert_frame_equal(before.drop(index=ix),out.drop(index=ix))
 save(layer,'new_fields.csv.gz');save(out,'requirements.csv.xz');save(out[out.is_open],'remaining_fields.csv.gz');players=out.groupby(K[:3]).agg(open_fields=('is_open','sum'),external_quality_fields=('needs_external_quality_review','sum')).reset_index();assert len(players)==77280;save(players,'player_match_readiness.csv.gz');matches=players.groupby(K[:2]).agg(open_fields=('open_fields','sum'),player_matches=('code','size'),affected_player_matches=('open_fields',lambda s:int(s.gt(0).sum()))).reset_index();assert len(matches)==2660;save(matches,'match_readiness.csv');save(out.groupby('field').agg(required=('field','size'),open_fields=('is_open','sum'),external_quality_fields=('needs_external_quality_review','sum')).reset_index(),'field_summary.csv');save(layer.groupby(['season','field']).agg(resolved=('code','size'),zero_values=('value',lambda s:int(s.eq(0).sum())),positive_values=('value',lambda s:int(s.gt(0).sum())),negative_values=('value',lambda s:int(s.lt(0).sum()))).reset_index(),'season_summary.csv')
 oldplayers=before.groupby(K[:3]).is_open.sum();oldmatches=oldplayers.groupby(level=[0,1]).sum();summary=dict(previous_open_fields=24285,new_fields=len(layer),reduction_percent=100*len(layer)/24285,by_field=layer.field.value_counts().to_dict(),unique_player_matches_with_new_fields=len(layer[K[:3]].drop_duplicates()),open_fields=int(out.is_open.sum()),unique_affected_player_matches=int(players.open_fields.gt(0).sum()),complete_player_matches=int(players.open_fields.eq(0).sum()),new_complete_player_matches=int(players.open_fields.eq(0).sum()-oldplayers.eq(0).sum()),complete_matches=int(matches.open_fields.eq(0).sum()),new_complete_matches=int(matches.open_fields.eq(0).sum()-oldmatches.eq(0).sum()),protected_rows_unchanged=True,raw_fpl_unchanged=True,scoring_qualified=False,published=False)
 (P/'results/summary.json').write_text(json.dumps(summary,indent=2)+'\n');print(json.dumps(summary,indent=2))
if __name__=='__main__':main()
